import csv, io, json, os, sys


def norm_id(s):
    return str(s).strip().casefold()


def norm_text(s):
    s = str(s).casefold()
    s = ''.join(ch if ch.isalnum() else ' ' for ch in s)
    return ' '.join(s.split())


def read_batch(path):
    """Return (batch, revision, status, records); record = (contest, {rank: [marks]}).
    A mark is ('c', id) or ('w', text)."""
    with open(path, encoding='utf-8-sig', newline='') as f:
        text = f.read()
    records = []
    if path.endswith('.jsonl'):
        head = None
        for line in text.split('\n'):
            line = line.strip()
            if not line:
                continue
            obj = json.loads(line)
            if head is None:
                head = obj
                continue
            ranks = {}
            for m in obj.get('marks') or []:
                r = int(m['rank'])
                lst = ranks.setdefault(r, [])
                if m.get('write_in') is not None:
                    lst.append(('w', m['write_in']))
                elif m.get('candidate') is not None:
                    lst.append(('c', m['candidate']))
            records.append((obj['contest'], ranks))
        head = head or {}
        return (str(head.get('batch')), int(str(head.get('revision')).strip()),
                str(head.get('status', 'final')).strip().lower(), records)
    # CSV
    lines = text.split('\n')
    meta = {}
    i = 0
    while i < len(lines):
        s = lines[i].strip()
        if s.startswith('#'):
            body = s[1:]
            if ':' in body:
                k, v = body.split(':', 1)
                meta[k.strip().lower()] = v.strip()
        elif s:
            break
        i += 1
    rows = csv.reader(io.StringIO('\n'.join(lines[i:])))
    header = None
    for row in rows:
        if not row or all(not c.strip() for c in row):
            continue
        if header is None:
            header = [c.strip() for c in row]
            continue
        d = dict(zip(header, row))
        ranks = {}
        for col, val in d.items():
            if col.lower().startswith('rank') and col[4:].isdigit():
                r = int(col[4:])
                marks = []
                for piece in val.split('|'):
                    p = piece.strip()
                    if not p:
                        continue
                    if p[:3].upper() == 'WI:':
                        marks.append(('w', p[3:]))
                    else:
                        marks.append(('c', p))
                ranks[r] = marks
        records.append((d['contest'].strip() if d.get('contest') else d.get('contest'), ranks))
    return (meta.get('batch'), int(meta.get('revision', '1').strip()),
            meta.get('status', 'final').strip().lower(), records)


def build_states(ranks, max_ranks, qualified, withdrawn):
    """Per-ranking states: ('skip',), ('pass',), ('choice', c), ('over',)."""
    states = []
    seen = set()
    for r in range(1, max_ranks + 1):
        cands = set()
        for kind, v in ranks.get(r, []):
            if kind == 'w':
                q = qualified.get(norm_text(v))
                if q is not None:
                    cands.add(q)
            else:
                cands.add(norm_id(v))
        if not cands:
            states.append(('skip',))
            continue
        cands -= withdrawn
        if not cands:
            states.append(('pass',))
            continue
        left = cands - seen
        seen |= cands
        if not left:
            states.append(('skip',))
        elif len(left) == 1:
            states.append(('choice', next(iter(left))))
        else:
            states.append(('over',))
    return states


def read_ballot(states, continuing):
    """Return the candidate counted for, or None if exhausted."""
    n = len(states)
    for i, st in enumerate(states):
        k = st[0]
        if k == 'choice':
            if st[1] in continuing:
                return st[1]
        elif k == 'over':
            return None
        elif k == 'skip':
            if i + 1 >= n or states[i + 1][0] == 'skip':
                return None
    return None


def count_contest(contest, ballots_ranks):
    max_ranks = int(contest.get('max_ranks', 0))
    out_id = {}
    withdrawn = set()
    active = []
    for c in contest.get('candidates', []):
        k = norm_id(c['id'])
        out_id[k] = c['id']
        if c.get('status', 'active') == 'withdrawn':
            withdrawn.add(k)
        else:
            active.append(k)
    qualified = {}
    for w in contest.get('write_ins', []):
        k = norm_id(w['id'])
        out_id[k] = w['id']
        active.append(k)
        for name in [w['name']] + list(w.get('aliases', [])):
            qualified[norm_text(name)] = k
    lot = [norm_id(x) for x in contest.get('lot_order', [])]
    lot_pos = {c: i for i, c in enumerate(lot)}

    states = [build_states(r, max_ranks, qualified, withdrawn) for r in ballots_ranks]
    total = len(states)
    continuing = list(dict.fromkeys(active))
    rounds = []
    history = []  # per round dict cand -> votes
    winner = None
    while True:
        cs = set(continuing)
        votes = {c: 0 for c in continuing}
        counted = 0
        for st in states:
            c = read_ballot(st, cs)
            if c is not None:
                votes[c] += 1
                counted += 1
        history.append(votes)
        rnd = {'round': len(history),
               'tallies': {out_id[c]: v for c, v in votes.items()},
               'exhausted': total - counted, 'eliminated': []}
        rounds.append(rnd)
        if counted == 0:
            break
        win = None
        for c, v in votes.items():
            if v * 2 > counted:
                win = c
        if win is None and len(continuing) == 1:
            win = continuing[0]
        if win is not None:
            winner = out_id[win]
            break
        zeros = [c for c in continuing if votes[c] == 0]
        if zeros:
            elim = zeros
        else:
            low = min(votes.values())
            tied = [c for c in continuing if votes[c] == low]
            for h in range(len(history) - 2, -1, -1):
                if len(tied) == 1:
                    break
                m = min(history[h][c] for c in tied)
                tied = [c for c in tied if history[h][c] == m]
            if len(tied) > 1:
                tied.sort(key=lambda c: lot_pos.get(c, -1))
                tied = [tied[-1]]
            elim = tied
        rnd['eliminated'] = sorted(out_id[c] for c in elim)
        continuing = [c for c in continuing if c not in elim]
    return {'contest': contest['id'], 'ballots': total, 'winner': winner, 'rounds': rounds}


def main():
    indir, outfile = sys.argv[1], sys.argv[2]
    with open(os.path.join(indir, 'election.json'), encoding='utf-8-sig') as f:
        election = json.load(f)
    cvr = os.path.join(indir, 'cvr')
    best = {}
    for name in sorted(os.listdir(cvr)):
        p = os.path.join(cvr, name)
        if not os.path.isfile(p) or not (name.endswith('.csv') or name.endswith('.jsonl')):
            continue
        b, rev, status, recs = read_batch(p)
        if b not in best or rev > best[b][0]:
            best[b] = (rev, status, recs)
    by_contest = {c['id']: [] for c in election['contests']}
    for rev, status, recs in best.values():
        if status == 'void':
            continue
        for cid, ranks in recs:
            if cid in by_contest:
                by_contest[cid].append(ranks)
    result = {'election': election.get('election'),
              'contests': [count_contest(c, by_contest[c['id']]) for c in election['contests']]}
    with open(outfile, 'w', encoding='utf-8') as f:
        json.dump(result, f, ensure_ascii=False)


if __name__ == '__main__':
    main()
